from z3 import *

# Create solver
s = Solver()

# Define color classes: partition 23 vertices into 3 groups
A = list(range(8))   # 0-7
B = list(range(8, 16))  # 8-15
C = list(range(16, 23))  # 16-22

# Edge variables (only between different color classes)
edges = {}
for a in A:
    for b in B:
        edges[(a, b)] = Bool(f"e_{a}_{b}")
for a in A:
    for c in C:
        edges[(a, c)] = Bool(f"e_{a}_{c}")
for b in B:
    for c in C:
        edges[(b, c)] = Bool(f"e_{b}_{c}")

# Count edges
edge_list = list(edges.values())
edge_count = Sum([If(e, 1, 0) for e in edge_list])
s.add(edge_count >= 44)

# No triangles (one vertex from each class, all connected)
for a in A:
    for b in B:
        for c in C:
            s.add(Not(And(edges[(a, b)], edges[(b, c)], edges[(a, c)])))

# No 4-cycles in A-B bipartite subgraph (no K_{2,2})
for i in range(len(A)):
    for j in range(i+1, len(A)):
        for k in range(len(B)):
            for l in range(k+1, len(B)):
                a1, a2 = A[i], A[j]
                b1, b2 = B[k], B[l]
                s.add(Not(And(edges[(a1, b1)], edges[(a1, b2)], edges[(a2, b1)], edges[(a2, b2)])))

# No 4-cycles in A-C bipartite subgraph
for i in range(len(A)):
    for j in range(i+1, len(A)):
        for k in range(len(C)):
            for l in range(k+1, len(C)):
                a1, a2 = A[i], A[j]
                c1, c2 = C[k], C[l]
                s.add(Not(And(edges[(a1, c1)], edges[(a1, c2)], edges[(a2, c1)], edges[(a2, c2)])))

# No 4-cycles in B-C bipartite subgraph
for i in range(len(B)):
    for j in range(i+1, len(B)):
        for k in range(len(C)):
            for l in range(k+1, len(C)):
                b1, b2 = B[i], B[j]
                c1, c2 = C[k], C[l]
                s.add(Not(And(edges[(b1, c1)], edges[(b1, c2)], edges[(b2, c1)], edges[(b2, c2)])))

print("Checking satisfiability...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    edge_result = []
    for e in edges:
        if m.evaluate(edges[e]) == True:
            edge_result.append(e)
    print(f"Found graph with {len(edge_result)} edges")
    print("Edges:", edge_result)
else:
    print("UNSAT with this partition")

# Verify the solution
edges = [(0, 11), (3, 10), (3, 11), (5, 13), (5, 15), (6, 8), (7, 9), (0, 16), (1, 16), (1, 22), (2, 17), (2, 22), (3, 19), (3, 21), (4, 17), (4, 19), (4, 20), (5, 18), (5, 19), (5, 22), (6, 20), (6, 21), (6, 22), (7, 16), (7, 17), (7, 18), (7, 21), (8, 16), (8, 19), (9, 22), (10, 16), (10, 17), (10, 18), (10, 22), (11, 17), (11, 20), (12, 18), (12, 21), (13, 16), (13, 21), (14, 19), (14, 20), (14, 21), (14, 22), (15, 17), (15, 21)]

print(f"Number of edges: {len(edges)}")

# Check 3-coloring
color = {}
for v in range(8):
    color[v] = 0
for v in range(8, 16):
    color[v] = 1
for v in range(16, 23):
    color[v] = 2

# Verify all edges connect different colors
for u, v in edges:
    assert color[u] != color[v], f"Edge ({u},{v}) has same color"
print("3-coloring verified")

# Check no triangles
from itertools import combinations
edge_set = set()
for u, v in edges:
    edge_set.add((min(u,v), max(u,v)))

for u, v, w in combinations(range(23), 3):
    if (min(u,v), max(u,v)) in edge_set and (min(u,w), max(u,w)) in edge_set and (min(v,w), max(v,w)) in edge_set:
        print(f"Triangle found: ({u},{v},{w})")
        break
else:
    print("No triangles found")

# Check no 4-cycles
for u, v, w, x in combinations(range(23), 4):
    cycle_edges = [(min(u,v), max(u,v)), (min(v,w), max(v,w)), (min(w,x), max(w,x)), (min(u,x), max(u,x))]
    if all(e in edge_set for e in cycle_edges):
        print(f"4-cycle found: ({u},{v},{w},{x})")
        break
    cycle_edges2 = [(min(u,v), max(u,v)), (min(v,x), max(v,x)), (min(x,w), max(x,w)), (min(u,w), max(u,w))]
    if all(e in edge_set for e in cycle_edges2):
        print(f"4-cycle found: ({u},{v},{x},{w})")
        break
else:
    print("No 4-cycles found")

print("Girth >= 5 verified")
print("All checks passed!")

